//! Deterministic search metadata.
use crabber::core::ToolInfo;
/// Model-facing search contract.
pub fn info() -> ToolInfo {
    ToolInfo {name:"search".into(),description:"Search workspace files via ripgrep. Defaults to regex mode and preserves existing pattern/path/timeout behavior. Optional glob filters, literal mode, ignore-case mode, context lines, and match limit are supported. Per-call timeout defaults to 60s and is capped at 600s. The host resolves the ripgrep binary once; configuration files are always disabled.".into(),parameters:serde_json::json!({"properties": {"pattern": {"minLength": 1, "description": "Regex pattern. Forwarded to ripgrep via -e. Inline flags such as (?i) are supported.", "type": "string"}, "path": {"description": "Workspace-relative search root. Optional; empty or \".\" searches the entire workspace.", "type": "string"}, "timeout_seconds": {"maximum": 600, "minimum": 0, "description": "Per-call timeout in seconds. 0 or omitted applies the default (60s). Cap is 600s.", "type": "integer"}, "glob": {"oneOf": [{"minLength": 1, "type": "string"}, {"items": {"minLength": 1, "type": "string"}, "minItems": 1, "type": "array"}], "description": "Optional ripgrep include glob or globs, forwarded as repeated -g filters."}, "literal": {"description": "If true, search for pattern as a fixed string via ripgrep -F. Default false.", "type": "boolean"}, "ignore_case": {"description": "If true, search case-insensitively via ripgrep -i. Default false.", "type": "boolean"}, "context": {"maximum": 20, "minimum": 0, "description": "Number of before and after context lines to return. Default 0; cap is 20.", "type": "integer"}, "limit": {"maximum": 1000, "minimum": 0, "description": "Maximum matches to return. Default 200; cap is 1000.", "type": "integer"}}, "additionalProperties": false, "required": ["pattern"], "type": "object"}),retry_safe:true,required_permissions:vec![crabber_tools_core::permission::FS_READ.into(),crabber_tools_core::permission::PROCESS_EXEC.into()]}
}
